            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import combinations


def _route(data, minimum, exact, inclusive=True):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = bits.get(start, 0)
    budget = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (start, initial_mask, 0)
    distances = {initial: data["start"]}
    queue = [(data["start"], start, initial_mask, 0)]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full
                and (not exact or used == budget)):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < budget:
                duration = max(minimum, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, used + 1))
            for duration, next_used in choices:
                next_time = depart + duration
                if next_time > data["deadline"] or (not inclusive and next_time == data["deadline"]):
                    continue
                next_node = edge["v"]
                next_mask = mask | bits.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_used))
    return {"arrival": None}


def _build_route(minimum, exact, inclusive=True):
    return lambda data: _route(data, minimum, exact, inclusive)


def _build_ledger():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_resolver():
    def active_dependencies(row, features):
        return [dep for dep in row.get("deps", [])
                if not dep.get("feature") or dep["feature"] in features]

    def acyclic(graph):
        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True

        return all(visit(name) for name in graph)

    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        names = sorted(packages)

        def search(pending, bounds, chosen, graph):
            if not pending:
                if not acyclic(graph):
                    return None
                return chosen

            name, low, high = pending[0]
            rest = pending[1:]
            bounds = dict(bounds)
            old_low, old_high = bounds.get(name, (1, 9))
            low, high = max(low, old_low), min(high, old_high)
            if low > high:
                return None
            bounds[name] = (low, high)
            if name in chosen:
                if not low <= chosen[name] <= high:
                    return None
                return search(rest, bounds, chosen, graph)

            rows = [row for row in packages.get(name, [])
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            best = None
            for row in rows:
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_graph = {key: list(value) for key, value in graph.items()}
                next_graph.setdefault(name, [])
                next_pending = list(rest)
                for dep in active_dependencies(row, features):
                    next_graph[name].append(dep["name"])
                    next_pending.append((dep["name"], dep["min"], dep["max"]))
                result = search(next_pending, bounds, next_chosen, next_graph)
                if result is not None and (best is None or
                        tuple(result.get(n, -1) for n in names) <
                        tuple(best.get(n, -1) for n in names)):
                    best = result
            return best

        pending = [(name, limits[0], limits[1])
                   for name, limits in data["roots"].items()]
        result = search(pending, {}, {}, {})
        return {"versions": result} if result is not None else {"error": "unsatisfiable"}
    return solve


def _build_scheduler():
    def solve(data):
        jobs = data["jobs"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in combinations([job for job in jobs if job["id"] not in blocked], data["k"]):
            ids = sorted(job["id"] for job in subset)
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            intervals = sorted((job["start"], job["end"]) for job in subset)
            if any(intervals[i][0] < intervals[i - 1][1]
                   for i in range(1, len(intervals))):
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value
                    or (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


SOLVERS = {
    "component_01": _build_route(1, False),
    "component_02": _build_route(1, True),
    "component_03": _build_route(2, False),
    "component_04": _build_route(2, True),
    "component_05": _build_route(1, False),
    "component_06": _build_ledger(),
    "component_07": _build_resolver(),
    "component_08": _build_scheduler(),
}
